#include <bits/stdc++.h>
using namespace std;

const long long mod = 998244353;

long long n, m, p, q, x, y;
unordered_map<long long, long long> dp[2];

long long fn(long long x, long long y, long long st, int type) {
    if (dp[type].count(st)) return dp[type][st];
    if (st == 1) {
        if (type == 0) return x;
        return y;
    }
    if (st % 2 == 1) {
        long long res = (x * fn(x, y, st - 1, type) + y * fn(x, y, st - 1, (type + 1) % 2)) % mod;
        return dp[type][st] = res;
    } else {
        long long nch = fn(x, y, st / 2, 1);
        long long ch = fn(x, y, st / 2, 0);
        long long ans = 0;
        if (type == 0) {
            ans = (ch * ch + nch * nch) % mod;
        } else {
            ans = (2 * ch * nch) % mod;
        }
        return dp[type][st] = ans;
    }
}

long long bin_pow(long long x, long long st) {
    if (st == 0) return 1;
    if (st == 1) return x;
    long long m = st / 2;
    long long ans = bin_pow(x, m);
    if (st % 2 == 0) {
        return (ans * ans) % mod;
    } else {
        return (((ans * ans) % mod) * x) % mod;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m >> p >> q;
    long long total = n * m;
    x = q - p + 1;
    if (p % 2 == 0) x = x - x / 2;
    else x /= 2;
    y = (q - p + 1) - x;

    if (((n & m) ) % 2 == 0) {
        long long ans = fn(x, y, total, 0);
        cout << ans << "\n";
    } else {
        long long ans = bin_pow(x + y, total);
        cout << ans << "\n";
    }
    return 0;
}
